#!/usr/bin/env node
// claude-tweaks statusline wrapper.
// Resolves the latest installed claude-tweaks version from the plugin cache
// at runtime, so settings.json never needs to be updated on plugin upgrades.
// Generated by bin/install-statusline-wrapper.js — re-run /claude-tweaks:init
// (or the installer directly) if the cache path layout ever changes.
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');
const os = require('os');

function resolveConfigDirRoot() {
  const fromEnv = process.env.CLAUDE_CONFIG_DIR;
  if (typeof fromEnv === 'string' && fromEnv.trim()) return fromEnv.replace(/[\\/]+$/, '');
  return path.join(os.homedir(), '.claude');
}

const CACHE = path.join(
  resolveConfigDirRoot(),
  'plugins',
  'cache',
  'claude-tweaks-marketplace',
  'claude-tweaks',
);

function pickLatest() {
  const entries = fs.readdirSync(CACHE).filter((v) => /^\d+\.\d+\.\d+$/.test(v));
  if (entries.length === 0) return null;
  entries.sort((a, b) => {
    const pa = a.split('.').map(Number);
    const pb = b.split('.').map(Number);
    return pa[0] - pb[0] || pa[1] - pb[1] || pa[2] - pb[2];
  });
  return entries[entries.length - 1];
}

try {
  const latest = pickLatest();
  if (!latest) process.exit(0);
  const target = path.join(CACHE, latest, 'bin', 'claude-tweaks-statusline.js');
  if (!fs.existsSync(target)) process.exit(0);

  // Prefer running the real statusline logic in-process — requiring the
  // resolved target and calling its exported main() directly, instead of
  // spawning a second Node interpreter merely to run it, saves a full
  // Node cold-start (~30ms) on every single statusline render. Falls back
  // to spawning a child process for any cached version whose
  // claude-tweaks-statusline.js predates the `main` export (keeps working
  // through the upgrade window instead of hard-failing on a mismatch).
  let mod = null;
  try {
    mod = require(target);
  } catch {
    mod = null;
  }
  if (mod && typeof mod.main === 'function') {
    mod
      .main()
      .catch(() => process.stdout.write(''))
      .then(() => process.exit(0));
  } else {
    const child = spawn('node', [target], { stdio: 'inherit', windowsHide: true });
    child.on('exit', (code) => process.exit(code || 0));
    child.on('error', () => process.exit(0));
  }
} catch {
  process.exit(0);
}
